theme.css:
:root {
  --background: #f3f5fb;
  --foreground: #010101;
  --card: #ffffff;
  --card-foreground: #010101;
  --popover: #ffffff;
  --popover-foreground: #010101;
  --primary: #002d9e;
  --primary-foreground: #f3f5f9;
  --secondary: #0a0a0a;
  --secondary-foreground: #f5f7fb;
  --muted: #f5f5f5;
  --muted-foreground: #454545;
  --accent: #002d9e;
  --accent-foreground: #ffffff;
  --destructive: #9b0033;
  --destructive-foreground: #ffffff;
  --border: #e3e3e3;
  --input: #ffffff;
  --ring: #2359e2;
  --chart-1: #007bff;
  --chart-2: #13c9aa;
  --chart-3: #cf3fd9;
  --chart-4: #8f3c1e;
  --chart-5: #17ab92;
  --radius: 1rem;
  --sidebar: #001B3C;
  --sidebar-foreground: #f4f5fc;
  --sidebar-primary: #19398d;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #19398d;
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: #d4d4d4;
  --sidebar-ring: #19398d;
  --font-sans: Inter, ui-sans-serif, sans-serif, system-ui;
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --shadow-color: #1a2137;
  --shadow-opacity: 0.05;
  --shadow-blur: 2px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 1px;
  --letter-spacing: 0em;
  --spacing: 0.24rem;
}

.dark {
  --background: #050505;
  --foreground: #fafafa;
  --card: #0a0a0a;
  --card-foreground: #fafafa;
  --popover: #171717;
  --popover-foreground: #fafafa;
  --primary: #6a8dd8;
  --primary-foreground: #0a0a0a;
  --secondary: #171717;
  --secondary-foreground: #fafafa;
  --muted: #262626;
  --muted-foreground: #a1a1a1;
  --accent: #404040;
  --accent-foreground: #fafafa;
  --destructive: #cd6e7b;
  --destructive-foreground: #fafafa;
  --border: #282828;
  --input: #121212;
  --ring: #6a8dd8;
  --chart-1: #6a8dd8;
  --chart-2: #2062ce;
  --chart-3: #4c5f00;
  --chart-4: #cc7455;
  --chart-5: #4bb3a1;
  --radius: 0.5rem;
  --sidebar: #0a0a0a;
  --sidebar-foreground: #fafafa;
  --sidebar-primary: #6a8dd8;
  --sidebar-primary-foreground: #fafafa;
  --sidebar-accent: #262626;
  --sidebar-accent-foreground: #fafafa;
  --sidebar-border: #282828;
  --sidebar-ring: #6a8dd8;
  --font-sans: Inter, ui-sans-serif, sans-serif, system-ui;
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --shadow-color: #000000;
  --shadow-opacity: 0.05;
  --shadow-blur: 2px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 1px;
  --letter-spacing: 0em;
  --spacing: 0.24rem;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-radius: var(--radius);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-font-sans: var(--font-sans);
  --color-font-serif: var(--font-serif);
  --color-font-mono: var(--font-mono);
  --color-shadow-color: var(--shadow-color);
  --color-shadow-opacity: var(--shadow-opacity);
  --color-shadow-blur: var(--shadow-blur);
  --color-shadow-spread: var(--shadow-spread);
  --color-shadow-offset-x: var(--shadow-offset-x);
  --color-shadow-offset-y: var(--shadow-offset-y);
  --color-letter-spacing: var(--letter-spacing);
  --color-spacing: var(--spacing);
}
